import{_ as s,o as t,c as i,ao as a}from"./chunks/framework.ucUddl5u.js";const u=JSON.parse('{"title":"Contributing","description":"","frontmatter":{},"headers":[],"relativePath":"contributing.md","filePath":"contributing.md","lastUpdated":null}'),n={name:"contributing.md"};function o(r,e,l,d,h,p){return t(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="Contributing" tabindex="-1">Contributing <a class="header-anchor" href="#Contributing" aria-label="Permalink to &quot;Contributing {#Contributing}&quot;">​</a></h1><p>Ship of Tools has a small number of working conventions and one firm rule about where decisions are recorded. This page covers both, plus how to build and test.</p><p>Before adding a feature, read <a href="./design/requirements">Requirements</a> — it defines scope. This page and the design pages define structure.</p><h2 id="Working-conventions" tabindex="-1">Working conventions <a class="header-anchor" href="#Working-conventions" aria-label="Permalink to &quot;Working conventions {#Working-conventions}&quot;">​</a></h2><ul><li><p><strong>Julia is the canonical language</strong> for plugin code, the ABI, and any Julia-aware logic. Use it expressively — lean on multiple dispatch and the type system. See <a href="./extend/abi">The Dispatch ABI</a>.</p></li><li><p><strong>Rust is for plumbing</strong> — the TUI, IPC, file watching, process supervision. Keep it boring and predictable.</p></li><li><p><strong>Plotting is CairoMakie</strong> when generating plots in Julia.</p></li><li><p><strong>Eat dogfood.</strong> Core handlers ship as plugins to themselves; the core modes and standard file types are methods on the same abstract types a third-party plugin extends. If core seems to want privileged access, the rule is to <em>fix the ABI</em>, not to special-case core. This keeps the extension surface honest.</p></li><li><p><strong>Boundaries are serialization seams.</strong> <code>TreeNode</code> and <code>PreviewPayload</code> carry opaque, kernel-defined payloads. Rust never learns about new entity kinds — adding a <code>FileType</code> (and, by design, a <code>Mode</code>) requires zero Rust changes. See <a href="./design/protocol">Line Protocol</a>.</p></li><li><p><strong>Reactive over eager</strong> for staleness, refresh, and indexing. Visible drift (e.g., a stale-annotation badge) is a feature, not a bug.</p></li><li><p><strong>Defer until forced.</strong> If a feature can wait for a later phase, it should.</p></li></ul><h2 id="The-decision-process" tabindex="-1">The decision process <a class="header-anchor" href="#The-decision-process" aria-label="Permalink to &quot;The decision process {#The-decision-process}&quot;">​</a></h2><p>Cross-cutting decisions get documented — <strong>never only in a code comment or a commit message.</strong> Some decisions are explicitly deferred (multi-agent coordination, remote transport variants, MCP as the internal protocol, an embedded editor, a user-preferences mechanism, automatic plot capture); when you reach for one of these, check whether it is still deferred before building it.</p><p>Plan amendments go through a pull request. The phase plan is a committed document — argue changes in the diff, not in side channels. See the <a href="./design/roadmap">Roadmap</a> for the milestone structure.</p><h2 id="Build-and-test" tabindex="-1">Build and test <a class="header-anchor" href="#Build-and-test" aria-label="Permalink to &quot;Build and test {#Build-and-test}&quot;">​</a></h2><p>The repository is a Julia umbrella package with a Rust workspace inside it.</p><p>Julia — run the umbrella suite and the core package suite:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Pkg</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Pkg</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">test</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()                          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># umbrella package</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Pkg</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">test</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ConceptExplorerCore&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># core, from its own environment</span></span></code></pre></div><p>Rust — the frontend, backend, and protocol crates live under <code>rust/</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --manifest-path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rust/Cargo.toml</span></span></code></pre></div><h2 id="Developing-the-frontend:-rebuild-without-dropping-your-session" tabindex="-1">Developing the frontend: rebuild without dropping your session <a class="header-anchor" href="#Developing-the-frontend:-rebuild-without-dropping-your-session" aria-label="Permalink to &quot;Developing the frontend: rebuild without dropping your session {#Developing-the-frontend:-rebuild-without-dropping-your-session}&quot;">​</a></h2><p>Ship of Tools can rebuild and restart its own frontend — so you can edit the frontend, recompile, and relaunch into the new binary without leaving the app. The moving parts:</p><ul><li><p><strong>Staged-copy supervisor.</strong> The launcher copies the built <code>sot</code> into a staging directory (<code>%LOCALAPPDATA%\\sot\\bin\\</code>) and runs the app from that copy inside a respawn loop. Because the running file is the staged copy, <code>cargo build --release</code> can overwrite <code>rust/target/release/</code> freely — no running-exe file lock — and you see build output live.</p></li><li><p><strong>Exit-75 sentinel.</strong> The frontend requests a relaunch by exiting with code <strong>75</strong>; any other code is a real quit. A background watcher polls for a relaunch-request sentinel file; on seeing it, the frontend exits 75 and the supervisor re-stages the (freshly built) binary and respawns with <code>--relaunched</code>.</p></li><li><p><strong>The drawer reopens plain.</strong> On <code>--relaunched</code>, the frontend opens into the Terminal drawer with a plain shell and runs nothing. A session that must survive frontend relaunches (the dev driver above is one) is a <strong>local capsule session</strong>, held by its own supervisor.</p></li></ul><p>The one-command driver is <code>scripts/relaunch-sot.ps1</code>: it runs <code>cargo build --release</code> and drops the relaunch sentinel <strong>only on a green build</strong> — a failed build leaves the running app untouched.</p><h3 id="Prefer-the-relaunch-loop-over-killing-the-frontend" tabindex="-1">Prefer the relaunch loop over killing the frontend <a class="header-anchor" href="#Prefer-the-relaunch-loop-over-killing-the-frontend" aria-label="Permalink to &quot;Prefer the relaunch loop over killing the frontend {#Prefer-the-relaunch-loop-over-killing-the-frontend}&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Use the relaunch loop, not a process kill</p><p>The dev <code>claude</code> session that drives frontend development is a local capsule session, not a passenger of the frontend process, so it survives either way. Still restart through the relaunch loop — <code>scripts/relaunch-sot.ps1</code> (build → sentinel → exit-75 → re-stage → respawn) — rather than a process kill: it re-stages the freshly built binary and keeps the supervisor&#39;s SSH tunnel alive across the swap.</p></div><p>Note that changes to the <em>supervisor script itself</em> (<code>launch-sot.ps1</code>) are not picked up by the exit-75 in-place loop — those require a full restart of the launcher. The exit-75 path only re-stages the frontend binary.</p><h2 id="See-also" tabindex="-1">See also <a class="header-anchor" href="#See-also" aria-label="Permalink to &quot;See also {#See-also}&quot;">​</a></h2><ul><li><p><a href="./design/requirements">Requirements</a> — the source of truth for scope.</p></li><li><p><a href="./design/roadmap">Roadmap</a> — phase plan and milestones.</p></li><li><p><a href="https://github.com/kalidke/ship-of-tools/tree/main/docs/adr" target="_blank" rel="noreferrer">Design decisions</a> — the ADRs in <code>docs/adr/</code>.</p></li></ul><h2 id="Releases" tabindex="-1">Releases <a class="header-anchor" href="#Releases" aria-label="Permalink to &quot;Releases {#Releases}&quot;">​</a></h2><p>Releases are tag-driven: <code>scripts/release.sh</code> stamps the versions and tags, and CI builds, smoke-tests and publishes the artifacts (<a href="https://github.com/kalidke/ship-of-tools/blob/main/docs/adr/0030-versioning-release-and-auto-update.md" target="_blank" rel="noreferrer">ADR 0030</a>).</p>`,25)])])}const g=s(n,[["render",o]]);export{u as __pageData,g as default};
